def relation_quota_signal_config(operating_point: dict[str, Any] | None) -> dict[str, Any]:
    payload = dict(operating_point or {})
    expected = {
        "chunk_node_quality_protocol": CHUNK_NODE_QUALITY_PROTOCOL_VERSION,
        "chunk_node_quality_protocol_hash": chunk_node_quality_protocol_hash(),
        "out_evidence_mass_protocol": OUT_EVIDENCE_MASS_PROTOCOL_VERSION,
        "out_evidence_mass_protocol_hash": out_evidence_mass_protocol_hash(),
        "in_acceptance_capacity_protocol": IN_ACCEPTANCE_CAPACITY_PROTOCOL_VERSION,
        "in_acceptance_capacity_protocol_hash": in_acceptance_capacity_protocol_hash(),
        "relation_quota_protocol": RELATION_QUOTA_PROTOCOL_VERSION,
        "relation_quota_protocol_hash": relation_quota_protocol_hash(),
    }
    for field_name, expected_value in expected.items():
        supplied = payload.get(field_name)
        if supplied is not None and str(supplied) != expected_value:
            raise ValueError(f"{field_name} does not match the active implementation")
    supplied_scale = payload.get("quota_signal_scale")
    if supplied_scale is not None and float(supplied_scale) != RELATION_QUOTA_SIGNAL_SCALE:
        raise ValueError("quota_signal_scale does not match the active implementation")
    return {**expected, "quota_signal_scale": RELATION_QUOTA_SIGNAL_SCALE}


def relation_quota_prior_state_compatibility(state: ChunkRelationGraphState) -> tuple[bool, list[str]]:
    """Require any relation-derived prior to use the exact active relation/quota semantics."""

    reasons: list[str] = []
    if str(state.relation_protocol_version or "") != RELATION_PROTOCOL_VERSION:
        reasons.append("relation_protocol_version_mismatch")
    operating_point = dict(state.graph_operating_point_json or {})
    expected_fields = {
        "raw_strength_protocol_version": RELATION_RAW_STRENGTH_PROTOCOL_VERSION,
        "raw_strength_protocol_hash": relation_raw_strength_protocol_hash(),
        **relation_quota_signal_config(None),
    }
    for field_name, expected_value in expected_fields.items():
        supplied = operating_point.get(field_name)
        if supplied is None or str(supplied) != str(expected_value):
            reasons.append(f"operating_point_{field_name}_mismatch")
    try:
        calibration_config = edge_type_calibration_config(operating_point)
    except (TypeError, ValueError) as exc:
        reasons.append(f"operating_point_edge_calibration_mismatch:{exc}")
    else:
        diagnostics = dict(state.diagnostics_json or {})
        if diagnostics.get("edge_type_calibration_config_hash") != calibration_config["config_hash"]:
            reasons.append("edge_type_calibration_config_hash_mismatch")
    if str(state.graph_operating_point_hash or "") != stable_hash(operating_point):
        reasons.append("graph_operating_point_hash_mismatch")
    return not reasons, reasons


def relation_operating_point_prior(
    state: ChunkRelationGraphState | None,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Return an operating-point prior only when its complete protocol bundle is current."""

    if state is None:
        return None, {
            "status": "absent",
            "source_graph_state_id": None,
            "compatible": False,
            "reused": False,
            "reasons": ["no_previous_active_relation_state"],
        }
    compatible, reasons = relation_quota_prior_state_compatibility(state)
    return (
        dict(state.graph_operating_point_json or {}) if compatible else None,
        {
            "status": "accepted" if compatible else "rejected",
            "source_graph_state_id": str(state.id),
            "source_relation_protocol_version": str(state.relation_protocol_version or ""),
            "source_graph_operating_point_hash": str(state.graph_operating_point_hash or ""),
            "compatible": compatible,
            "reused": compatible,
            "reasons": reasons,
        },
    )


def relation_quota_card(*, lower: int, upper: int, signal: float, signal_role: str) -> dict[str, Any]:
    normalized_lower = int(lower)
    normalized_upper = int(upper)
    if normalized_lower < 0 or normalized_upper < normalized_lower:
        raise ValueError("relation quota bounds must satisfy 0 <= lower <= upper")
    normalized_signal = round(max(0.0, min(1.0, float(signal))), 6)
    scaled_signal = round(RELATION_QUOTA_SIGNAL_SCALE * normalized_signal, 6)
    increment = int(math.floor(math.log2(1.0 + scaled_signal)))
    value = max(normalized_lower, min(normalized_upper, normalized_lower + increment))
    return {
        "value": value,
        "lower": normalized_lower,
        "upper": normalized_upper,
        "signal_role": signal_role,
        "signal": normalized_signal,
        "quota_signal_scale": RELATION_QUOTA_SIGNAL_SCALE,
        "scaled_signal": scaled_signal,
        "log2_increment": increment,
        "protocol_version": RELATION_QUOTA_PROTOCOL_VERSION,
        "protocol_hash": relation_quota_protocol_hash(),
        "query_relevance": False,
    }


