def relation_raw_strength(
    *,
    semantic: float,
    reciprocity: float,
    rank_score: float,
    node_quality_pair: float,
) -> float:
    return normalized_strength(
        0.75 * float(semantic)
        + 0.15 * float(reciprocity)
        + 0.07 * float(rank_score)
        + 0.03 * float(node_quality_pair)
    )


