def _entry_semantic_input_packet(proof: dict[str, Any]) -> dict[str, Any]:
    return {
        "protocol_version": ENTRY_SEMANTIC_AGGREGATION_PROTOCOL_VERSION,
        "node_id": str(proof.get("node_id") or ""),
        "layer": str(proof.get("layer") or ""),
        "support_chunk_ids": list(proof.get("support_chunk_ids") or []),
        "semantic_dense_support_facts": list(
            proof.get("semantic_dense_support_facts") or []
        ),
    }


def validate_entry_replay_proof(
    raw_proof: dict[str, Any],
    *,
    expected_node_id: str | None = None,
    expected_layer: str | None = None,
) -> dict[str, Any]:
    proof = dict(raw_proof or {})
    failures: list[str] = []
    node_id = str(proof.get("node_id") or "")
    layer = str(proof.get("layer") or "")
    if proof.get("protocol_version") != ENTRY_REPLAY_PROOF_PROTOCOL_VERSION:
        failures.append("replay_proof_protocol_version")
    if layer not in {"coarse", "mid"}:
        failures.append("replay_proof_layer")
    if not node_id:
        failures.append("replay_proof_node_id")
    if expected_node_id is not None and node_id != str(expected_node_id):
        failures.append("replay_proof_expected_node_id")
    if expected_layer is not None and layer != str(expected_layer):
        failures.append("replay_proof_expected_layer")

    support_chunk_ids = [
        str(value) for value in (proof.get("support_chunk_ids") or []) if str(value)
    ]
    if support_chunk_ids != sorted(set(support_chunk_ids)):
        failures.append("replay_proof_support_chunk_ids")
    if int(proof.get("support_count") or 0) != len(support_chunk_ids):
        failures.append("replay_proof_support_count")

    dense_facts: list[dict[str, Any]] = []
    for raw_fact in proof.get("semantic_dense_support_facts") or []:
        if not isinstance(raw_fact, dict):
            failures.append("replay_proof_dense_fact_type")
            continue
        chunk_id = str(raw_fact.get("chunk_id") or "")
        try:
            dense_score = round(float(raw_fact.get("dense_score")), 6)
        except (TypeError, ValueError):
            failures.append("replay_proof_dense_score")
            continue
        vector_business_fact_hash = str(
            raw_fact.get("active_contextual_vector_business_fact_hash") or ""
        )
        if len(vector_business_fact_hash) != 64 or any(
            character not in "0123456789abcdef"
            for character in vector_business_fact_hash
        ):
            failures.append("replay_proof_dense_vector_business_fact_hash")
        dense_facts.append(
            {
                "chunk_id": chunk_id,
                "dense_score": dense_score,
                "active_contextual_vector_business_fact_hash": (
                    vector_business_fact_hash
                ),
            }
        )
        if not chunk_id or chunk_id not in support_chunk_ids:
            failures.append("replay_proof_dense_support_scope")
        if not 0.0 < dense_score <= 1.0:
            failures.append("replay_proof_dense_score_range")
    expected_dense_order = sorted(
        dense_facts,
        key=lambda item: (-float(item["dense_score"]), str(item["chunk_id"])),
    )[:4]
    if dense_facts != expected_dense_order or len(dense_facts) > 4:
        failures.append("replay_proof_dense_top4_order")
    expected_support_ids = [item["chunk_id"] for item in dense_facts]
    if list(proof.get("semantic_support_chunk_ids") or []) != expected_support_ids:
        failures.append("replay_proof_semantic_support_ids")
    if int(proof.get("semantic_support_match_count") or 0) != len(dense_facts):
        failures.append("replay_proof_semantic_support_match_count")
    if dense_facts:
        max_score = float(dense_facts[0]["dense_score"])
        mean_score = sum(float(item["dense_score"]) for item in dense_facts) / len(
            dense_facts
        )
        expected_semantic_score = round(
            (0.75 * max_score) + (0.25 * mean_score), 6
        )
    else:
        expected_semantic_score = 0.0
    if abs(
        float(proof.get("semantic_score") or 0.0) - expected_semantic_score
    ) > 1e-6:
        failures.append("replay_proof_semantic_score")
    expected_semantic_candidate = bool(dense_facts) and expected_semantic_score > 0.0
    if proof.get("semantic_candidate") is not expected_semantic_candidate:
        failures.append("replay_proof_semantic_candidate")
    if proof.get("semantic_input_hash") != stable_hash(
        _entry_semantic_input_packet(proof)
    ):
        failures.append("replay_proof_semantic_input_hash")

    for field_name in (
        "query_facet_packet_hash",
        "active_topology_state_identity_hash",
        "topology_state_hash",
        "topology_node_business_fact_hash",
        "topology_prior_hash",
        "dense_replay_input_hash",
    ):
        field_value = str(proof.get(field_name) or "")
        if len(field_value) != 64 or any(
            character not in "0123456789abcdef" for character in field_value
        ):
            failures.append(field_name)
    if (
        proof.get("neutral_start_cost_protocol_version")
        != ENTRY_NEUTRAL_START_COST_PROTOCOL_VERSION
    ):
        failures.append("neutral_start_cost_protocol_version")
    observed_proof_hash = str(proof.get("proof_hash") or "")
    proof_hash_input = dict(proof)
    proof_hash_input.pop("proof_hash", None)
    if observed_proof_hash != stable_hash(proof_hash_input):
        failures.append("replay_proof_hash")
    if failures:
        raise EntrySelectionTraceInvariantError(
            "entry replay proof is non-replayable: "
            + ", ".join(sorted(set(failures)))
        )
    return proof


def validate_entry_candidate_card(
    raw_card: dict[str, Any],
    *,
    entry_strength: float | None = None,
    expected_entry_strength: float | None = None,
    expected_node_id: str | None = None,
    expected_layer: str | None = None,
    expected_replay_proof: dict[str, Any] | None = None,
) -> dict[str, Any]:
    card = dict(raw_card or {})
    topology = dict(card.get("topology") or {})
    node_id = str(card.get("node_id") or "")
    layer = str(card.get("layer") or "")
    failures: list[str] = []
    if card.get("protocol_version") != ENTRY_SELECTION_PROTOCOL_VERSION:
        failures.append("protocol_version")
    if card.get("protocol_hash") != entry_selection_protocol_hash():
        failures.append("protocol_hash")
    if expected_node_id is not None and node_id != str(expected_node_id):
        failures.append("expected_node_id")
    if expected_layer is not None and layer != str(expected_layer):
        failures.append("expected_layer")
    replay_proof = validate_entry_replay_proof(
        dict(card.get("replay_proof") or {}),
        expected_node_id=node_id,
        expected_layer=layer,
    )
    if expected_replay_proof is not None:
        frozen_expected = validate_entry_replay_proof(
            dict(expected_replay_proof),
            expected_node_id=node_id,
            expected_layer=layer,
        )
        if replay_proof != frozen_expected:
            failures.append("frozen_expected_replay_proof")

    if topology.get("protocol_version") != ENTRY_TOPOLOGY_PROTOCOL_VERSION:
        failures.append("topology_protocol_version")
    if topology.get("protocol_hash") != entry_topology_protocol_hash():
        failures.append("topology_protocol_hash")
    if stable_hash(topology) != replay_proof.get("topology_prior_hash"):
        failures.append("topology_provenance")
    if int(card.get("support_count") or 0) != int(
        replay_proof.get("support_count") or 0
    ):
        failures.append("support_count_provenance")
    semantic_fields = {
        "semantic_score": float(card.get("semantic_score") or 0.0),
        "semantic_candidate": bool(card.get("semantic_candidate")),
        "semantic_support_chunk_ids": list(
            card.get("semantic_support_chunk_ids") or []
        ),
        "semantic_support_match_count": int(
            card.get("semantic_support_match_count") or 0
        ),
    }
    expected_semantic_fields = {
        "semantic_score": float(replay_proof.get("semantic_score") or 0.0),
        "semantic_candidate": bool(replay_proof.get("semantic_candidate")),
        "semantic_support_chunk_ids": list(
            replay_proof.get("semantic_support_chunk_ids") or []
        ),
        "semantic_support_match_count": int(
            replay_proof.get("semantic_support_match_count") or 0
        ),
    }
    if semantic_fields != expected_semantic_fields:
        failures.append("semantic_business_provenance")
    semantic_candidate = semantic_fields["semantic_candidate"]
    semantic_score = semantic_fields["semantic_score"]
    semantic_count = semantic_fields["semantic_support_match_count"]
    semantic_ids = semantic_fields["semantic_support_chunk_ids"]
    if not (
        semantic_candidate
        == (semantic_score > 0.0)
        == (semantic_count > 0)
        == bool(semantic_ids)
    ) or semantic_count != len(semantic_ids):
        failures.append("semantic_candidate_invariant")
    for authority_field in (
        "lexical_overlap_used_as_query_relevance",
        "topology_used_as_path_distance",
        "node_weight_used_as_query_relevance",
        "gray_zone_rule_inputs_modified",
        "neutral_start_cost_is_query_relevance",
    ):
        if card.get(authority_field) is not False:
            failures.append(authority_field)
    if int(card.get("model_call_count") or 0) != 0:
        failures.append("model_call_count")
    if (
        card.get("neutral_start_cost_protocol_version")
        != ENTRY_NEUTRAL_START_COST_PROTOCOL_VERSION
    ):
        failures.append("neutral_start_cost_protocol_version")
    observed_hash = str(card.get("candidate_card_hash") or "")
    hash_input = dict(card)
    hash_input.pop("candidate_card_hash", None)
    if observed_hash != stable_hash(hash_input):
        failures.append("candidate_card_hash")
    effective_expected_strength = (
        expected_entry_strength
        if expected_entry_strength is not None
        else entry_strength
    )
    if effective_expected_strength is not None:
        card_strength = card.get("entry_strength")
        if card_strength is None or abs(
            float(card_strength) - normalized_strength(effective_expected_strength)
        ) > 1e-6:
            failures.append("entry_strength")
    if card.get("entry_strength_source") == (
        "topology_admission_versioned_neutral_start_cost"
    ) and abs(
        float(card.get("entry_strength") or 0.0)
        - ENTRY_TOPOLOGY_NEUTRAL_START_STRENGTH
    ) > 1e-6:
        failures.append("neutral_start_cost_value")
    if failures:
        raise EntrySelectionTraceInvariantError(
            "entry candidate card is non-replayable: "
            + ", ".join(sorted(set(failures)))
        )
    return card


def empty_entry_selection_audit(
    *, retrieval_granularity: RetrievalGranularity
) -> dict[str, Any]:
    layer_audits = {
        layer: {
            "protocol_version": ENTRY_SELECTION_PROTOCOL_VERSION,
            "protocol_hash": entry_selection_protocol_hash(),
            "topology_protocol_version": ENTRY_TOPOLOGY_PROTOCOL_VERSION,
            "topology_protocol_hash": entry_topology_protocol_hash(),
            "replay_proof_protocol_version": (
                ENTRY_REPLAY_PROOF_PROTOCOL_VERSION
            ),
            "dense_replay_protocol_version": ENTRY_DENSE_REPLAY_PROTOCOL_VERSION,
            "neutral_start_cost_protocol_version": (
                ENTRY_NEUTRAL_START_COST_PROTOCOL_VERSION
            ),
            "layer": layer,
            "intent_strategy": "not_evaluated_no_active_chunks",
            "candidate_count": 0,
            "semantic_candidate_count": 0,
            "selected_ids": [],
            "selected_count": 0,
            "top_n": 0,
            "frozen_replay_proofs_by_node": {},
            "lexical_overlap_used_as_query_relevance": False,
            "topology_used_as_path_distance": False,
            "node_weight_used_as_query_relevance": False,
            "neutral_start_cost_is_query_relevance": False,
            "gray_zone_rule_inputs_modified": False,
            "model_call_count": 0,
        }
        for layer in ("coarse", "mid")
    }
    if retrieval_granularity == "mid":
        layer_audits["coarse"]["skipped_by_granularity"] = "mid"
    return {
        "protocol_version": ENTRY_SELECTION_PROTOCOL_VERSION,
        "protocol_hash": entry_selection_protocol_hash(),
        "topology_protocol_version": ENTRY_TOPOLOGY_PROTOCOL_VERSION,
        "topology_protocol_hash": entry_topology_protocol_hash(),
        "replay_proof_protocol_version": ENTRY_REPLAY_PROOF_PROTOCOL_VERSION,
        "dense_replay_protocol_version": ENTRY_DENSE_REPLAY_PROTOCOL_VERSION,
        "neutral_start_cost_protocol_version": (
            ENTRY_NEUTRAL_START_COST_PROTOCOL_VERSION
        ),
        "layers": layer_audits,
        "lexical_overlap_used_as_query_relevance": False,
        "topology_used_as_path_distance": False,
        "node_weight_used_as_query_relevance": False,
        "neutral_start_cost_is_query_relevance": False,
        "gray_zone_rule_inputs_modified": False,
        "model_call_count": 0,
    }


def validate_entry_selection_trace_audit(
    raw_audit: dict[str, Any],
) -> dict[str, Any]:
    audit = dict(raw_audit or {})
    failures: list[str] = []
    expected_values = {
        "protocol_version": ENTRY_SELECTION_PROTOCOL_VERSION,
        "protocol_hash": entry_selection_protocol_hash(),
        "topology_protocol_version": ENTRY_TOPOLOGY_PROTOCOL_VERSION,
        "topology_protocol_hash": entry_topology_protocol_hash(),
        "replay_proof_protocol_version": ENTRY_REPLAY_PROOF_PROTOCOL_VERSION,
        "dense_replay_protocol_version": ENTRY_DENSE_REPLAY_PROTOCOL_VERSION,
        "neutral_start_cost_protocol_version": (
            ENTRY_NEUTRAL_START_COST_PROTOCOL_VERSION
        ),
        "lexical_overlap_used_as_query_relevance": False,
        "topology_used_as_path_distance": False,
        "node_weight_used_as_query_relevance": False,
        "neutral_start_cost_is_query_relevance": False,
        "gray_zone_rule_inputs_modified": False,
        "model_call_count": 0,
    }
    for field_name, expected_value in expected_values.items():
        if audit.get(field_name) != expected_value:
            failures.append(field_name)
    layers = audit.get("layers")
    if not isinstance(layers, dict):
        failures.append("layers")
        layers = {}
    for layer in ("coarse", "mid"):
        layer_audit = layers.get(layer)
        if not isinstance(layer_audit, dict):
            failures.append(f"layers.{layer}")
            continue
        if layer_audit.get("protocol_version") != ENTRY_SELECTION_PROTOCOL_VERSION:
            failures.append(f"layers.{layer}.protocol_version")
        if layer_audit.get("protocol_hash") != entry_selection_protocol_hash():
            failures.append(f"layers.{layer}.protocol_hash")
        if (
            layer_audit.get("topology_protocol_version")
            != ENTRY_TOPOLOGY_PROTOCOL_VERSION
        ):
            failures.append(f"layers.{layer}.topology_protocol_version")
        if layer_audit.get("topology_protocol_hash") != entry_topology_protocol_hash():
            failures.append(f"layers.{layer}.topology_protocol_hash")
        if (
            layer_audit.get("replay_proof_protocol_version")
            != ENTRY_REPLAY_PROOF_PROTOCOL_VERSION
        ):
            failures.append(f"layers.{layer}.replay_proof_protocol_version")
        if (
            layer_audit.get("dense_replay_protocol_version")
            != ENTRY_DENSE_REPLAY_PROTOCOL_VERSION
        ):
            failures.append(f"layers.{layer}.dense_replay_protocol_version")
        if (
            layer_audit.get("neutral_start_cost_protocol_version")
            != ENTRY_NEUTRAL_START_COST_PROTOCOL_VERSION
        ):
            failures.append(
                f"layers.{layer}.neutral_start_cost_protocol_version"
            )
        if layer_audit.get("layer") != layer:
            failures.append(f"layers.{layer}.layer")
        if int(layer_audit.get("model_call_count") or 0) != 0:
            failures.append(f"layers.{layer}.model_call_count")
        for authority_field in (
            "lexical_overlap_used_as_query_relevance",
            "topology_used_as_path_distance",
            "node_weight_used_as_query_relevance",
            "neutral_start_cost_is_query_relevance",
            "gray_zone_rule_inputs_modified",
        ):
            if layer_audit.get(authority_field) is not False:
                failures.append(f"layers.{layer}.{authority_field}")
        proofs = layer_audit.get("frozen_replay_proofs_by_node")
        if not isinstance(proofs, dict):
            failures.append(f"layers.{layer}.frozen_replay_proofs_by_node")
            continue
        if proofs:
            top_level_dense_replay_hash = str(
                audit.get("dense_replay_input_hash") or ""
            )
            if (
                len(top_level_dense_replay_hash) != 64
                or layer_audit.get("dense_replay_input_hash")
                != top_level_dense_replay_hash
            ):
                failures.append(f"layers.{layer}.top_level_dense_replay_input_hash")
            identity = layer_audit.get("active_topology_state_identity")
            if not isinstance(identity, dict) or not identity:
                failures.append(
                    f"layers.{layer}.active_topology_state_identity"
                )
            elif stable_hash(identity) != layer_audit.get(
                "active_topology_state_identity_hash"
            ):
                failures.append(
                    f"layers.{layer}.active_topology_state_identity_hash"
                )
            for hash_field in (
                "query_facet_packet_hash",
                "dense_replay_input_hash",
                "active_topology_state_identity_hash",
                "topology_state_hash",
            ):
                hash_value = str(layer_audit.get(hash_field) or "")
                if len(hash_value) != 64 or any(
                    character not in "0123456789abcdef"
                    for character in hash_value
                ):
                    failures.append(f"layers.{layer}.{hash_field}")
        for node_id, proof in proofs.items():
            try:
                validated_proof = validate_entry_replay_proof(
                    dict(proof or {}),
                    expected_node_id=str(node_id),
                    expected_layer=layer,
                )
                if validated_proof.get("query_facet_packet_hash") != (
                    layer_audit.get("query_facet_packet_hash")
                ):
                    failures.append(f"layers.{layer}.proof_query.{node_id}")
                if validated_proof.get("dense_replay_input_hash") != (
                    layer_audit.get("dense_replay_input_hash")
                ):
                    failures.append(
                        f"layers.{layer}.proof_dense_input.{node_id}"
                    )
                if validated_proof.get(
                    "active_topology_state_identity_hash"
                ) != layer_audit.get("active_topology_state_identity_hash"):
                    failures.append(f"layers.{layer}.proof_identity.{node_id}")
                if validated_proof.get("topology_state_hash") != (
                    layer_audit.get("topology_state_hash")
                ):
                    failures.append(
                        f"layers.{layer}.proof_topology_state.{node_id}"
                    )
            except EntrySelectionTraceInvariantError:
                failures.append(f"layers.{layer}.proof.{node_id}")
    if failures:
        raise EntrySelectionTraceInvariantError(
            "entry selection trace audit is non-replayable: "
            + ", ".join(sorted(set(failures)))
        )
    return audit


def validate_entry_query_facet_replay(
    raw_audit: dict[str, Any],
    *,
    query_facets: dict[str, Any],
) -> dict[str, Any]:
    audit = validate_entry_selection_trace_audit(raw_audit)
    expected_query_facet_packet_hash = stable_hash(query_facets)
    failures = [
        layer
        for layer in ("coarse", "mid")
        if (
            ((audit.get("layers") or {}).get(layer) or {}).get(
                "frozen_replay_proofs_by_node"
            )
            and ((audit.get("layers") or {}).get(layer) or {}).get(
                "query_facet_packet_hash"
            )
            != expected_query_facet_packet_hash
        )
    ]
    if failures:
        raise EntrySelectionTraceInvariantError(
            "entry query facets failed frozen replay: "
            + ", ".join(sorted(failures))
        )
    return audit


def validate_entry_topology_replay_against_database(
    db: Session,
    *,
    knowledge_base_id: str,
    raw_audit: dict[str, Any],
    query_facets: dict[str, Any],
) -> dict[str, Any]:
    """Replay frozen topology proof against immutable PostgreSQL business facts."""

    audit = validate_entry_query_facet_replay(
        raw_audit,
        query_facets=query_facets,
    )
    failures: list[str] = []
    for layer in ("coarse", "mid"):
        layer_audit = dict((audit.get("layers") or {}).get(layer) or {})
        proofs = dict(layer_audit.get("frozen_replay_proofs_by_node") or {})
        if not proofs:
            continue
        identity = dict(layer_audit.get("active_topology_state_identity") or {})
        state_id = str(identity.get("state_id") or "")
        if not state_id:
            failures.append(f"{layer}.state_id")
            continue
        if layer == "coarse":
            state = db.get(CoarseConceptState, state_id)
            if state is None:
                failures.append(f"{layer}.state_missing")
                continue
            expected_identity = {
                "layer": "coarse",
                "state_id": str(state.id),
                "state_hash": str(state.state_hash),
                "grounding_hash": str(state.grounding_hash),
                "mid_concept_state_id": str(state.mid_concept_state_id or ""),
                "state": str(identity.get("state") or "active"),
            }
            concepts = list(
                db.scalars(
                    select(CoarseConcept).where(
                        CoarseConcept.coarse_state_id == state.id,
                        CoarseConcept.state == "active",
                    )
                ).all()
            )
            edges = list(
                db.scalars(
                    select(CoarseConceptEdge).where(
                        CoarseConceptEdge.coarse_state_id == state.id
                    )
                ).all()
            )
        else:
            state = db.get(MidConceptState, state_id)
            if state is None:
                failures.append(f"{layer}.state_missing")
                continue
            expected_identity = {
                "layer": "mid",
                "state_id": str(state.id),
                "state_hash": str(state.state_hash),
                "grounding_hash": str(state.grounding_hash),
                "chunk_relation_graph_state_id": str(
                    state.chunk_relation_graph_state_id or ""
                ),
                "state": str(identity.get("state") or "active"),
            }
            concepts = list(
                db.scalars(
                    select(MidConcept).where(
                        MidConcept.concept_state_id == state.id,
                        MidConcept.state == "active",
                    )
                ).all()
            )
            edges = list(
                db.scalars(
                    select(MidConceptEdge).where(
                        MidConceptEdge.concept_state_id == state.id
                    )
                ).all()
            )
        if str(state.knowledge_base_id) != str(knowledge_base_id):
            failures.append(f"{layer}.knowledge_base_id")
            continue
        if identity != expected_identity:
            failures.append(f"{layer}.active_topology_state_identity")
            continue
        topology_state_proof = concept_entry_topology_state_proof(
            concepts,
            edges,
            layer=layer,
            active_topology_state_identity=expected_identity,
        )
        if topology_state_proof["topology_state_hash"] != layer_audit.get(
            "topology_state_hash"
        ):
            failures.append(f"{layer}.topology_state_hash")
        actual_priors = concept_entry_topology_priors(
            concepts,
            edges,
            layer=layer,
        )
        concept_by_id = {str(concept.id): concept for concept in concepts}
        node_fact_hashes = topology_state_proof["node_business_fact_hashes"]
        for node_id, raw_proof in proofs.items():
            proof = dict(raw_proof or {})
            if (
                node_id not in node_fact_hashes
                or node_id not in actual_priors
                or node_id not in concept_by_id
            ):
                failures.append(f"{layer}.node_missing.{node_id}")
                continue
            expected_support_chunk_ids = _concept_support_chunk_ids(
                concept_by_id[node_id],
                layer=layer,
            )
            if list(proof.get("support_chunk_ids") or []) != (
                expected_support_chunk_ids
            ) or int(proof.get("support_count") or 0) != len(
                expected_support_chunk_ids
            ):
                failures.append(f"{layer}.support_chunk_scope.{node_id}")
            if proof.get("topology_node_business_fact_hash") != (
                node_fact_hashes[node_id]
            ):
                failures.append(f"{layer}.node_business_fact.{node_id}")
            if proof.get("topology_prior_hash") != stable_hash(
                actual_priors[node_id]
            ):
                failures.append(f"{layer}.topology_prior.{node_id}")
    if failures:
        raise EntrySelectionTraceInvariantError(
            "persisted entry topology failed PostgreSQL replay: "
            + ", ".join(sorted(set(failures)))
        )
    return audit


